// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 fundAmount, address recipient) public {
        fundAmount = bound(fundAmount, 1, 1 ether);

        AcceptingReceiver recv = new AcceptingReceiver();
        address payable recvAddr = payable(address(recv));

        vm.deal(address(this), fundAmount);
        (bool okFund,) = address(c).call{value: fundAmount}("");
        require(okFund, "funding failed");

        vm.prank(address(this));
        c.withdrawAll(recvAddr);

        assertTrue(address(c).balance == 0);
    }
}

contract AcceptingReceiver {
    receive() external payable {}
}
